@Composable
fun AnimatedCanvas(
    modifier: Modifier = Modifier,
    onDrawWithCache: CacheDrawScope.(time: Float) -> DrawResult
) {
    val time by produceAnimationTime()
    Box(
        modifier.drawWithCache { onDrawWithCache(time) }
    )
}

private val maxTimeValue = 24.hours.inWholeMilliseconds

@Composable
fun produceAnimationTime(): State<Float> =
    produceState(0f) {
        while (true) {
            withInfiniteAnimationFrameMillis { frameTime ->
                val newTime = frameTime / 1000f
                // Reset every 24h to avoid precision issues
                value = if (newTime < maxTimeValue) newTime else 0f
            }
        }
    }

